    blocks, potential_road_points = identify_field_blocks(points, speed_threshold=25.0, proximity_threshold=30.0)

    # 計算面積
    total_area, paths = calculate_farming_area(blocks, field_boundary, working_width=2.0)

    # 輸出結果
    print(f"潛在馬路點數（速度>25 km/h）: {potential_road_points}")
    print(f"檢測到的耕作區塊數: {len(blocks)}")
    print(f"總耕作面積: {total_area:.2f} 平方公尺")

    # 可視化
    ref_lat, ref_lon = points[0][0], points[0][1]
    plot_path_and_boundary(paths, field_boundary, ref_lat, ref_lon)